// A plugin's CLAUDE.md is hand-written prose with ONE generated block in it:
// how that block is found and replaced. A leaf (no imports), so the fold that
// reads every CLAUDE.md (`claude-md-blocks.scan.ts`) is keyed by this code
// alone, not by docgen's closure.

export const AUTOGEN_BEGIN =
  "<!-- AUTOGENERATED:BEGIN — do not edit; regenerated by `./equin build` -->";
/**
 * Finds an existing block's BEGIN line by its marker, not its full text: the
 * wording after the marker (the CLI name it cites) may change, and an exact
 * match would then miss every existing block and append a second one.
 */
const BEGIN_LINE = /^<!-- AUTOGENERATED:BEGIN\b.*$/m;
export const AUTOGEN_END = "<!-- AUTOGENERATED:END -->";

/**
 * Strip any hand-written `## Plugin reference` section from a CLAUDE.md prose
 * prefix (the content before the AUTOGENERATED:BEGIN marker).
 *
 * When the autogenerated system was introduced it *appended* a block (which
 * itself opens with `## Plugin reference`) to files that already had a
 * hand-written section of the same name. The hand-written copy predates the
 * autogen system and drifts silently; the autogenerated block is the
 * authoritative, more-complete source of truth. This helper removes the stale
 * hand-written copy so only the autogenerated one remains.
 *
 * It also strips any dangling `AUTOGENERATED:END` marker left in the prose
 * by a prior manual edit that removed the matching BEGIN (the conflict-agent
 * anomaly).
 */
function stripStalePluginReference(prose: string): string {
  // Remove the last ## Plugin reference section in the prose and everything
  // that follows it (up to the end of the prose prefix). Using lastIndexOf
  // picks only the copy that sits immediately above the autogen block.
  const refMarker = "\n## Plugin reference\n";
  const refIdx = prose.lastIndexOf(refMarker);
  let cleaned = refIdx !== -1 ? prose.slice(0, refIdx) + "\n" : prose;

  // Remove any dangling AUTOGENERATED:END markers left without a matching BEGIN.
  cleaned = cleaned.replace(/<!--\s*AUTOGENERATED:END\s*-->\n?/g, "");

  return cleaned;
}

/**
 * `existing` with its autogen block replaced by `block` (appended when it has
 * none), the hand-written prose above it kept.
 */
export function spliceAutogenBlock(existing: string, block: string): string {
  const beginIdx = existing.search(BEGIN_LINE);
  if (beginIdx < 0) {
    const sep = existing.endsWith("\n") ? "\n" : "\n\n";
    return `${existing}${sep}${block}`;
  }
  const endIdx = existing.indexOf(AUTOGEN_END, beginIdx);
  if (endIdx < 0) {
    return `${existing.slice(0, beginIdx)}${block}`;
  }
  const after = existing.slice(endIdx + AUTOGEN_END.length);
  const trimmedAfter = after.startsWith("\n") ? after.slice(1) : after;
  const prose = stripStalePluginReference(existing.slice(0, beginIdx));
  return `${prose}${block}${trimmedAfter}`;
}

/**
 * The block `existing` is already spliced with: the ONE `block` for which
 * `spliceAutogenBlock(existing, block) === existing`, or null when no block
 * leaves it as it is (no block, no END, prose the splice would clean, or no
 * newline after END).
 *
 * Unique: the splice keeps a prefix and a suffix of `existing` that do not
 * depend on `block`, so at most one `block` fills the rest. The candidate is
 * that rest, and it is returned only once the splice itself confirms it — so
 * "the rendered block equals this" is exactly "splicing it changes nothing",
 * which is what lets a checker compare blocks instead of re-splicing a file.
 */
export function autogenFixedPoint(existing: string): string | null {
  const beginIdx = existing.search(BEGIN_LINE);
  if (beginIdx < 0) return null;
  const endIdx = existing.indexOf(AUTOGEN_END, beginIdx);
  if (endIdx < 0) return null;
  const candidate = `${existing.slice(beginIdx, endIdx + AUTOGEN_END.length)}\n`;
  return spliceAutogenBlock(existing, candidate) === existing
    ? candidate
    : null;
}
